//! Protocol coverage matrix — one row per [`ContractKey`] kind, the
//! audit that lets no protocol escape detection, joining, manual
//! confirmation, or dashboard visualization.
//!
//! The rows are generated by hand from the plan's audit table
//! (`docs/superpowers/plans/2026-10-18-topic-hub-and-protocol-coverage.md`,
//! "Protocol coverage audit") and rendered in prose in
//! `docs/protocol-coverage.md`. Each row answers four questions for
//! one kind:
//!
//! * `sensor` — the sensor(s) that mint the kind's contract facts;
//! * `resolver` — the joiner resolver that turns consumer facts into
//!   `Binds` edges (or `Unresolved`);
//! * `binding_supported` — whether `check_binding` and the
//!   `repos.yaml#bindings` grammar can confirm a link of this kind
//!   (true for all six since the Topic/Rpc/WebSocket/Table grammar
//!   landed);
//! * `view_edges` — the workspace-graph edge types through which the
//!   kind's contract surface reaches the dashboard view
//!   (`get_workspace_graph`). Every name here must be a member of
//!   [`WORKSPACE_GRAPH_EDGE_TYPES`](crate::server::mcp::federation_tools::WORKSPACE_GRAPH_EDGE_TYPES);
//!   an empty slice means the kind's dedicated legs are still outside
//!   the dashboard filter (named in `docs/protocol-coverage.md`).
//!
//! The [`tests`] module is the escape-proof half: adding a
//! `ContractKey` variant breaks its exhaustive `match` at compile
//! time, so the author must declare the kind's coverage row.

use crate::federation::contracts::model::ContractKey;

/// One row of the protocol coverage matrix. `kind` is the
/// [`ContractKey::kind`] tag for the variant the row describes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ProtocolCoverage {
    /// `ContractKey::kind()` tag (`"http"` / `"graphql"` / `"topic"` /
    /// `"rpc"` / `"websocket"` / `"table"`).
    pub kind: &'static str,
    /// The sensor(s) that mint this kind's contract facts, comma
    /// separated. Names are the `SensorOwner` module names.
    pub sensor: &'static str,
    /// The joiner resolver that turns this kind's consumer facts into
    /// `Binds` / `Unresolved`.
    pub resolver: &'static str,
    /// Whether `check_binding` + `repos.yaml#bindings` can confirm a
    /// link of this kind (the entry → `load_from_str` → `validate` →
    /// `apply_confirmed_binding` → `Binds { Confirmed }` chain).
    pub binding_supported: bool,
    /// Workspace-graph edge types through which this kind's contract
    /// surface is visible in the dashboard view. Every name is a
    /// member of `WORKSPACE_GRAPH_EDGE_TYPES` (asserted in the tests);
    /// empty means the kind's dedicated legs are outside the shipped
    /// dashboard filter.
    pub view_edges: &'static [&'static str],
}

/// The protocol coverage matrix: one row per [`ContractKey`] kind, in
/// the audit table's order (http, graphql, topic, rpc, websocket,
/// table).
pub fn coverage_matrix() -> Vec<ProtocolCoverage> {
    vec![
        ProtocolCoverage {
            kind: "http",
            sensor: "http_sensor, http_client_sensor, openapi_sensor",
            resolver: "HTTP ladder (consumer_http.rs)",
            binding_supported: true,
            view_edges: &["Calls"],
        },
        ProtocolCoverage {
            kind: "graphql",
            sensor:
                "graphql_consumer_sensor, graphql_provider_sensor, graphql_resolver_link_sensor",
            resolver: "resolve_graphql_consumer",
            binding_supported: true,
            // `ReadsFrom` / `ReadsField` / `HasField` / `ResponseSchema`
            // carry the GraphQL legs and are outside the shipped
            // dashboard filter; the call sites and SDL schemas render
            // as `Function` / `Schema` nodes only.
            view_edges: &[],
        },
        ProtocolCoverage {
            kind: "topic",
            sensor: "event_sensor",
            resolver: "resolve_topic_consumer",
            binding_supported: true,
            view_edges: &["Produces", "Consumes", "PayloadSchema"],
        },
        ProtocolCoverage {
            kind: "rpc",
            sensor:
                "grpc_provider_sensor, grpc_consumer_sensor, grpc_handler_link_sensor, proto_sensor",
            resolver: "resolve_rpc_consumer",
            binding_supported: true,
            // `RequestSchema` / `ResponseSchema` / `HasField` are the
            // RPC legs and are outside the shipped dashboard filter.
            view_edges: &[],
        },
        ProtocolCoverage {
            kind: "websocket",
            sensor: "websocket_sensor",
            resolver: "resolve_websocket_consumer",
            binding_supported: true,
            // `Uses` (handler → route) is the WebSocket leg and is
            // outside the shipped dashboard filter.
            view_edges: &[],
        },
        ProtocolCoverage {
            kind: "table",
            sensor: "sql_sensor",
            resolver: "resolve_table_consumer",
            binding_supported: true,
            // `ReadsTable` / `WritesTable` are the Table legs and are
            // outside the shipped dashboard filter.
            view_edges: &[],
        },
    ]
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::federation::contracts::model::{GraphqlOp, MethodSpec, RpcSystem};
    use crate::server::mcp::federation_tools::WORKSPACE_GRAPH_EDGE_TYPES;

    #[test]
    fn every_contract_kind_has_sensor_resolver_and_declared_binding_support() {
        // Exhaustive match: adding a ContractKey variant must break compilation
        // here, forcing the author to declare its coverage row.
        let rows = coverage_matrix();
        let _ = |k: &ContractKey| match k {
            ContractKey::Http { .. } => (),
            ContractKey::Topic { .. } => (),
            ContractKey::Rpc { .. } => (),
            ContractKey::Graphql { .. } => (),
            ContractKey::WebSocket { .. } => (),
            ContractKey::Table { .. } => (),
        };
        assert_eq!(rows.len(), 6);
        for row in &rows {
            assert!(
                !row.sensor.is_empty() && !row.resolver.is_empty(),
                "{row:?}"
            );
        }
        // Binding support must match reality (the Task 3 truth):
        let supported: Vec<&str> = rows
            .iter()
            .filter(|r| r.binding_supported)
            .map(|r| r.kind)
            .collect();
        assert_eq!(
            supported,
            vec!["http", "graphql", "topic", "rpc", "websocket", "table"]
        );
    }

    #[test]
    fn coverage_row_kinds_are_the_contract_key_kind_tags() {
        // Each row's `kind` must be the tag `ContractKey::kind()`
        // produces for that variant, and each variant must own exactly
        // one row.
        let rows = coverage_matrix();
        let exemplars = [
            ContractKey::Http {
                method: MethodSpec::Unknown,
                template: String::new(),
            },
            ContractKey::Graphql {
                op: GraphqlOp::Query,
                field: String::new(),
            },
            ContractKey::Topic {
                broker: String::new(),
                name: String::new(),
            },
            ContractKey::Rpc {
                system: RpcSystem::Grpc,
                service: String::new(),
                method: String::new(),
            },
            ContractKey::WebSocket {
                route: String::new(),
            },
            ContractKey::Table {
                name: String::new(),
            },
        ];
        for key in &exemplars {
            let matches: Vec<_> = rows.iter().filter(|r| r.kind == key.kind()).collect();
            assert_eq!(
                matches.len(),
                1,
                "expected exactly one coverage row for kind `{}`, got {matches:?}",
                key.kind()
            );
        }
    }

    #[test]
    fn coverage_view_edges_reference_the_real_workspace_filter_set() {
        // T2 carry-forward: `view_edges` names must be members of the
        // shipped `WORKSPACE_GRAPH_EDGE_TYPES` (referenced here, not
        // copied), so a filter rename or a drifted copy fails this
        // test instead of silently diverging from the dashboard.
        for row in coverage_matrix() {
            for e in row.view_edges {
                assert!(
                    WORKSPACE_GRAPH_EDGE_TYPES.contains(e),
                    "row `{}` names view edge `{e}`, which is not in WORKSPACE_GRAPH_EDGE_TYPES {WORKSPACE_GRAPH_EDGE_TYPES:?}",
                    row.kind
                );
            }
        }
        // T2 pinned the Topic row exactly: the hub's three legs.
        let topic = coverage_matrix()
            .into_iter()
            .find(|r| r.kind == "topic")
            .expect("topic row");
        assert_eq!(topic.view_edges, ["Produces", "Consumes", "PayloadSchema"]);
    }
}
